class Solution:
    def getMinimumDifference(self, root: Optional[TreeNode]) -> int:
        values = []
        def inorder(node):
            if not node:
                return
            inorder(node.left)
            values.append(node.val)
            inorder(node.right)
        inorder(root)
        min_diff = float('inf')
        for i in range(1, len(values)):
            diff = values[i] - values[i-1]
            if diff < min_diff:
                min_diff = diff
        return min_diff
